CREATE TABLE app_users (id UUID PRIMARY KEY,email VARCHAR(255) NOT NULL UNIQUE,password_hash VARCHAR(255) NOT NULL,full_name VARCHAR(150) NOT NULL,role VARCHAR(30) NOT NULL,status VARCHAR(30) NOT NULL,created_at TIMESTAMPTZ NOT NULL,updated_at TIMESTAMPTZ NOT NULL);
CREATE TABLE locations (id UUID PRIMARY KEY,name VARCHAR(180) NOT NULL,address VARCHAR(500) NOT NULL,latitude NUMERIC(9,6),longitude NUMERIC(9,6),created_at TIMESTAMPTZ NOT NULL,updated_at TIMESTAMPTZ NOT NULL);
CREATE TABLE accepted_item_types (id UUID PRIMARY KEY,code VARCHAR(80) NOT NULL UNIQUE,name VARCHAR(180) NOT NULL,description VARCHAR(500),base_tokens INTEGER NOT NULL DEFAULT 1 CHECK(base_tokens>=0),bonus_tokens INTEGER NOT NULL DEFAULT 0 CHECK(bonus_tokens>=0),active BOOLEAN NOT NULL DEFAULT TRUE,created_at TIMESTAMPTZ NOT NULL,updated_at TIMESTAMPTZ NOT NULL);
CREATE TABLE bins (id UUID PRIMARY KEY,public_code VARCHAR(100) NOT NULL UNIQUE,name VARCHAR(180) NOT NULL,location_id UUID NOT NULL REFERENCES locations(id),status VARCHAR(30) NOT NULL,capacity_percent INTEGER NOT NULL DEFAULT 0 CHECK(capacity_percent BETWEEN 0 AND 100),last_seen_at TIMESTAMPTZ,created_at TIMESTAMPTZ NOT NULL,updated_at TIMESTAMPTZ NOT NULL);
CREATE TABLE bin_accepted_items (bin_id UUID NOT NULL REFERENCES bins(id) ON DELETE CASCADE,item_type_id UUID NOT NULL REFERENCES accepted_item_types(id),PRIMARY KEY(bin_id,item_type_id));
CREATE TABLE devices (id UUID PRIMARY KEY,bin_id UUID NOT NULL REFERENCES bins(id),device_code VARCHAR(100) NOT NULL UNIQUE,secret_hash VARCHAR(255) NOT NULL,status VARCHAR(30) NOT NULL,firmware_version VARCHAR(80),last_heartbeat_at TIMESTAMPTZ,created_at TIMESTAMPTZ NOT NULL,updated_at TIMESTAMPTZ NOT NULL);
CREATE TABLE deposit_sessions (id UUID PRIMARY KEY,user_id UUID NOT NULL REFERENCES app_users(id),bin_id UUID NOT NULL REFERENCES bins(id),status VARCHAR(40) NOT NULL,session_date DATE NOT NULL,started_at TIMESTAMPTZ NOT NULL,expires_at TIMESTAMPTZ NOT NULL,completed_at TIMESTAMPTZ,created_at TIMESTAMPTZ NOT NULL,updated_at TIMESTAMPTZ NOT NULL,CONSTRAINT uq_session_user_bin_day UNIQUE(user_id,bin_id,session_date));
CREATE TABLE device_events (id UUID PRIMARY KEY,device_id UUID NOT NULL REFERENCES devices(id),external_event_id VARCHAR(160) NOT NULL,event_type VARCHAR(50) NOT NULL,recorded_at TIMESTAMPTZ NOT NULL,received_at TIMESTAMPTZ NOT NULL,ir_detected BOOLEAN NOT NULL,weight_change_grams NUMERIC(10,3),claimed_item_code VARCHAR(80),classification_confidence NUMERIC(5,4),payload_json TEXT,processing_status VARCHAR(40) NOT NULL,created_at TIMESTAMPTZ NOT NULL,updated_at TIMESTAMPTZ NOT NULL,CONSTRAINT uq_device_external_event UNIQUE(device_id,external_event_id));
CREATE TABLE deposits (id UUID PRIMARY KEY,session_id UUID NOT NULL UNIQUE REFERENCES deposit_sessions(id),device_event_id UUID NOT NULL UNIQUE REFERENCES device_events(id),item_type_id UUID REFERENCES accepted_item_types(id),verification_status VARCHAR(40) NOT NULL,ir_detected BOOLEAN NOT NULL,measured_weight_grams NUMERIC(10,3),classification_confidence NUMERIC(5,4),rejection_reason VARCHAR(500),verified_at TIMESTAMPTZ NOT NULL,created_at TIMESTAMPTZ NOT NULL,updated_at TIMESTAMPTZ NOT NULL);
CREATE TABLE vouchers (id UUID PRIMARY KEY,partner_name VARCHAR(180) NOT NULL,title VARCHAR(220) NOT NULL,description VARCHAR(800),token_cost INTEGER NOT NULL CHECK(token_cost>0),inventory INTEGER NOT NULL CHECK(inventory>=0),valid_from TIMESTAMPTZ,valid_until TIMESTAMPTZ,status VARCHAR(30) NOT NULL,image_url VARCHAR(1000),created_at TIMESTAMPTZ NOT NULL,updated_at TIMESTAMPTZ NOT NULL);
CREATE TABLE redemptions (id UUID PRIMARY KEY,user_id UUID NOT NULL REFERENCES app_users(id),voucher_id UUID NOT NULL REFERENCES vouchers(id),token_cost INTEGER NOT NULL CHECK(token_cost>0),redemption_code VARCHAR(100) NOT NULL UNIQUE,status VARCHAR(30) NOT NULL,used_at TIMESTAMPTZ,created_at TIMESTAMPTZ NOT NULL,updated_at TIMESTAMPTZ NOT NULL);
CREATE TABLE token_ledger (id UUID PRIMARY KEY,user_id UUID NOT NULL REFERENCES app_users(id),deposit_id UUID REFERENCES deposits(id),redemption_id UUID REFERENCES redemptions(id),transaction_type VARCHAR(40) NOT NULL,amount INTEGER NOT NULL CHECK(amount<>0),description VARCHAR(500) NOT NULL,created_at TIMESTAMPTZ NOT NULL,updated_at TIMESTAMPTZ NOT NULL);
CREATE INDEX idx_bins_status ON bins(status);
CREATE INDEX idx_sessions_user_created ON deposit_sessions(user_id,created_at DESC);
CREATE INDEX idx_sessions_bin_status ON deposit_sessions(bin_id,status);
CREATE INDEX idx_ledger_user_created ON token_ledger(user_id,created_at DESC);
